-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. This expression index covers the second branch of the OR in run-secret-redaction valuesForIssue (context_snapshot -> 'paperclipIssue' ->> 'id'); without it the planner cannot BitmapOr with heartbeat_runs_company_ctx_issue_created_idx and falls back to a full sequential scan that detoasts every run's context_snapshot on every issue comments read.
CREATE INDEX IF NOT EXISTS "heartbeat_runs_company_ctx_paperclip_issue_created_idx" ON "heartbeat_runs" USING btree ("company_id", ("context_snapshot" -> 'paperclipIssue' ->> 'id'), "created_at" DESC);
